int main(int argc,char**argv){CHECK(argc==2);corpus(argv[1]);state(argv[1]);using morrow::fs_directory_v1::page;using morrow::fs_directory_v1::directory_state;static_assert(!std::is_copy_constructible_v<page>);static_assert(!std::is_copy_constructible_v<directory_state>);record p=named(argv[1],"file-no-length");page first;CHECK(first.decode(p.wire,p.wn)==0);page moved(std::move(first));CHECK(!first.has_value());const uint8_t bad[8]={0};CHECK(moved.decode(bad,8)!=0&&moved.has_value());mfd_page_view_v1 v;CHECK(moved.view(v)==0&&v.entry_count==1);std::vector<uint8_t>out={1,2,3};page empty;CHECK(empty.encode(out)!=0&&out==std::vector<uint8_t>({1,2,3}));CHECK(moved.encode(out)==0);CHECK(first.decode(out)==0);first=std::move(moved);CHECK(!moved.has_value()&&first.has_value());printf("METHOD cpp_directory_move_only_and_error_preserves_owner_vector PASS\n");std::array<uint8_t,32>epoch{};epoch.fill(1);directory_state s;CHECK(s.create(epoch)==0);page result;CHECK(s.admit(p.wire,p.wn,result)==0);directory_state transferred(std::move(s));CHECK(!s.has_value()&&transferred.has_value());CHECK(transferred.admit(bad,8,result)!=0&&result.has_value());CHECK(result.view(v)==0&&v.entry_count==1);CHECK(transferred.release()==0);mfd_state_snapshot_v1 snap;CHECK(transferred.snapshot(snap)==0&&snap.released==1&&snap.resident_ids==0);printf("METHOD cpp_directory_state_move_and_failed_admit_preserve_page PASS\n");drop(&p);return 0;}
